14	/// The one bloc behind "Meus Registros" (contracts/records-bloc.md,
15	/// contracts/records-bloc-extension.md). Depends only on
16	/// `EntriesRepository` — never `SessionRepository`, `ConnectivityChecker`,
17	/// nor `SessionBloc` or any of its event/state types (research.md R4/R5/R11,
18	/// requirements.md RF07's own acceptance criterion).
19	class RecordsBloc extends Bloc<RecordsEvent, RecordsState> {
20	  // The public parameter names (`entriesRepository`/`debounceDuration`) must
21	  // stay underscore-free; an initializing formal would force the private
22	  // field names onto them instead.
23	  RecordsBloc({
24	    required EntriesRepository entriesRepository,
25	    Duration debounceDuration = const Duration(milliseconds: 300),
26	  }) : _entriesRepository = entriesRepository, // ignore: prefer_initializing_formals
27	       _debounceDuration = debounceDuration, // ignore: prefer_initializing_formals
28	       super(const RecordsLoading()) {
29	    on<RecordsStarted>(_onStarted);
30	    on<NextPageRequested>(_onNextPageRequested);
31	    on<PageLoadRetried>(_onPageLoadRetried);
32	    on<RecordsLocalCacheRefreshed>(_onLocalCacheRefreshed);
33	    on<SearchTextChanged>(_onSearchTextChanged);
34	    on<SearchDebounceElapsed>(_onSearchDebounceElapsed);
35	    on<FilterSheetApplied>(_onFilterSheetApplied);
36	    on<FilterChipRemoved>(_onFilterChipRemoved);
37	    on<FiltersAndSearchCleared>(_onFiltersAndSearchCleared);
38	    on<CriteriaLoadRetried>(_onCriteriaLoadRetried);
39	  }
40	
41	  final EntriesRepository _entriesRepository;
42	  final Duration _debounceDuration;
43	  final _reauthController = StreamController<void>.broadcast();
44	
45	  String _query = '';
46	  DateRangeOption _dateRange = DateRangeOption.allTime;
47	  Set<EntrySource> _entryTypes = {};
48	  Timer? _debounceTimer;
49	  int _fetchGeneration = 0;
50	
51	  /// A one-shot side effect, not a state (research.md R5) —
52	  /// `RecordsPage` listens to this to raise the "Sessão expirada" overlay.
53	  Stream<void> get reauthRequired => _reauthController.stream;
54	
55	  Future<void> _onStarted(RecordsStarted event, Emitter<RecordsState> emit) async {
56	    emit(const RecordsLoading());
57	    await _loadFirstPage(emit);
58	  }
59	
60	  Future<void> _onPageLoadRetried(PageLoadRetried event, Emitter<RecordsState> emit) async {
61	    final current = state;
62	    if (current is RecordsLoadFailure) {
63	      emit(const RecordsLoading());
64	      await _loadFirstPage(emit);
65	    } else if (current is RecordsLoaded && current.pageLoadFailure != null) {
66	      await _fetchNextPage(current, emit);
67	    }
68	  }
69	
70	  Future<void> _loadFirstPage(Emitter<RecordsState> emit) async {
71	    final result = await _entriesRepository.list();
72	    result.match(
73	      (failure) {
74	        if (failure is AuthExpiredFailure) _reauthController.add(null);
75	        emit(RecordsLoadFailure(failure));
76	      },
77	      (page) => emit(
78	        RecordsLoaded(
79	          entries: EntryMerger.merge(
80	            primary: page.entries,
81	            secondary: _entriesRepository.cachedEntries,
82	          ),
83	          nextCursor: page.nextCursor,
84	          isLoadingMore: false,
85	        ),
86	      ),
87	    );
88	  }
89	
90	  Future<void> _onNextPageRequested(
91	    NextPageRequested event,
92	    Emitter<RecordsState> emit,
93	  ) async {
94	    final current = state;
95	    if (current is! RecordsLoaded || current.hasReachedEnd || current.isLoadingMore) {
96	      return;
97	    }
98	    await _fetchNextPage(current, emit);
99	  }
100	
101	  Future<void> _fetchNextPage(RecordsLoaded current, Emitter<RecordsState> emit) async {
102	    final generation = ++_fetchGeneration;
103	    emit(current.copyWith(isLoadingMore: true, pageLoadFailure: null));
104	
105	    final bounds = _dateRange.boundsAt(DateTime.now());
106	    final result = await _entriesRepository.list(
107	      cursor: current.nextCursor,
108	      source: _entryTypes.isEmpty ? null : _entryTypes.single,
109	      dateFrom: bounds.from,
110	      dateTo: bounds.to,
111	    );
112	    if (generation != _fetchGeneration) return;
113	
114	    result.match(
115	      (failure) {
116	        if (failure is AuthExpiredFailure) {
117	          _reauthController.add(null);
118	          // entries/cursor unchanged, isLoadingMore resets to false, no
119	          // pageLoadFailure — FR-007's "restored exactly as it was" holds
120	          // by construction.
121	          emit(current.copyWith(isLoadingMore: false, pageLoadFailure: null));
122	        } else {
123	          emit(current.copyWith(isLoadingMore: false, pageLoadFailure: failure));
124	        }
125	      },
126	      (page) => emit(
127	        current.copyWith(
128	          entries: EntryMerger.merge(
129	            primary: current.entries + page.entries,
130	            secondary: _entriesRepository.cachedEntries,
131	          ),
132	          nextCursor: page.nextCursor,
133	          isLoadingMore: false,
134	          pageLoadFailure: null,
135	        ),
136	      ),
137	    );
138	  }
139	
140	  void _onLocalCacheRefreshed(
141	    RecordsLocalCacheRefreshed event,
142	    Emitter<RecordsState> emit,
143	  ) {
144	    final current = state;
145	    if (current is! RecordsLoaded || current.hasAnyActiveCriteria) return;
146	    emit(
147	      current.copyWith(
148	        entries: EntryMerger.merge(
149	          primary: current.entries,
150	          secondary: _entriesRepository.cachedEntries,
151	        ),
152	      ),
153	    );
154	  }
155	
156	  // --- Search text -> debounce -> fetch (FR-001/FR-002, research.md R4/R6) ---
157	
158	  Future<void> _onSearchTextChanged(SearchTextChanged event, Emitter<RecordsState> emit) async {
159	    _debounceTimer?.cancel();
160	    _query = event.text;
161	    if (event.text.isEmpty) {
162	      // Acceptance Scenario 3 / Edge Case: no request for empty text —
163	      // refetch immediately under whatever filters are still active.
164	      await _fetchForCriteria(emit);
165	      return;
166	    }
167	    _debounceTimer = Timer(
168	      _debounceDuration,
169	      () => add(SearchDebounceElapsed(event.text)),
170	    );
171	  }
172	
173	  Future<void> _onSearchDebounceElapsed(
174	    SearchDebounceElapsed event,
175	    Emitter<RecordsState> emit,
176	  ) async {
177	    // Superseded by a newer keystroke/clear that arrived after the timer fired.
178	    if (event.text != _query) return;
179	    await _fetchForCriteria(emit);
180	  }
181	
182	  // --- Filter sheet / chips / clear (FR-003/FR-005/FR-007, research.md R1/R6) ---
183	
184	  Future<void> _onFilterSheetApplied(
185	    FilterSheetApplied event,
186	    Emitter<RecordsState> emit,
187	  ) async {
188	    _dateRange = event.dateRange;
189	    _entryTypes = event.entryTypes;
190	    await _fetchForCriteria(emit);
191	  }
192	
193	  Future<void> _onFilterChipRemoved(
194	    FilterChipRemoved event,
195	    Emitter<RecordsState> emit,
196	  ) async {
197	    switch (event.chip) {
198	      case DateRangeChip():
199	        _dateRange = DateRangeOption.allTime;
200	      case EntryTypeChip(source: final s):
201	        _entryTypes = {..._entryTypes}..remove(s);
202	    }
203	    await _fetchForCriteria(emit);
204	  }
205	
206	  Future<void> _onFiltersAndSearchCleared(
207	    FiltersAndSearchCleared event,
208	    Emitter<RecordsState> emit,
209	  ) async {
210	    _debounceTimer?.cancel();
211	    _query = '';
212	    _dateRange = DateRangeOption.allTime;
213	    _entryTypes = {};
214	    await _fetchForCriteria(emit);
215	  }
216	
217	  Future<void> _onCriteriaLoadRetried(
218	    CriteriaLoadRetried event,
219	    Emitter<RecordsState> emit,
220	  ) async {
221	    // Re-attempts the exact same last-applied criteria (_query/_dateRange/_entryTypes).
222	    await _fetchForCriteria(emit);
223	  }
224	
225	  // --- The core fetch (bounded-vs-paginated branch — research.md R1, generation guard — R6) ---
226	
227	  Future<void> _fetchForCriteria(Emitter<RecordsState> emit) async {
228	    final generation = ++_fetchGeneration;
229	    final current = state;
230	    if (current is RecordsLoaded) {
231	      emit(
232	        current.copyWith(
233	          isApplyingCriteria: true,
234	          searchQuery: _query,
235	          dateRange: _dateRange,
236	          entryTypes: _entryTypes,
237	        ),
238	      );
239	    }
240	    // Nothing to show yet (still on RecordsLoading/RecordsLoadFailure) —
241	    // RecordsStarted's own _loadFirstPage() owns the very first fetch; this
242	    // path is only reachable once a RecordsLoaded exists.
243	
244	    final bounds = _dateRange.boundsAt(DateTime.now());
245	    final result = await _resolveEntries(
246	      query: _query,
247	      dateFrom: bounds.from,
248	      dateTo: bounds.to,
249	      types: _entryTypes,
250	    );
251	    if (generation != _fetchGeneration) return; // superseded — discard silently (FR-005a)
252	
253	    result.match(
254	      (failure) {
255	        final latest = state;
256	        if (latest is! RecordsLoaded) return;
257	        if (failure is AuthExpiredFailure) {
258	          _reauthController.add(null);
259	          // entries/criteria unchanged, no criteriaLoadFailure — same
