7	  const RecordsEvent();
8	
9	  @override
10	  List<Object?> get props => [];
11	}
12	
13	/// `RecordsPage.initState` — triggers the first page fetch.
14	class RecordsStarted extends RecordsEvent {
15	  const RecordsStarted();
16	}
17	
18	/// The list's `ScrollController` crosses a near-bottom threshold, and
19	/// `!hasReachedEnd && !isLoadingMore`.
20	class NextPageRequested extends RecordsEvent {
21	  const NextPageRequested();
22	}
23	
24	/// The user taps "Tentar novamente" on a failed first load
25	/// (`RecordsLoadFailure`) or a failed further-page load
26	/// (`RecordsLoaded.pageLoadFailure`).
27	class PageLoadRetried extends RecordsEvent {
28	  const PageLoadRetried();
29	}
30	
31	/// `RecordsPage`, once the insertion-modal `showModalBottomSheet` future
32	/// resolves (research.md R10) — re-merges `cachedEntries` into the currently
33	/// displayed list, no network call.
34	class RecordsLocalCacheRefreshed extends RecordsEvent {
35	  const RecordsLocalCacheRefreshed();
36	}
37	
38	/// The search bar's `onChanged`, fired on every keystroke.
39	class SearchTextChanged extends RecordsEvent {
40	  const SearchTextChanged(this.text);
41	
42	  final String text;
43	
44	  @override
45	  List<Object?> get props => [text];
46	}
47	
48	/// Fired by the bloc's own `Timer`, 300 ms after the last [SearchTextChanged]
49	/// with non-empty text; never dispatched directly by any widget.
50	class SearchDebounceElapsed extends RecordsEvent {
51	  const SearchDebounceElapsed(this.text);
52	
53	  final String text;
54	
55	  @override
56	  List<Object?> get props => [text];
57	}
