60	class FilterSheetApplied extends RecordsEvent {
61	  const FilterSheetApplied({required this.dateRange, required this.entryTypes});
62	
63	  final DateRangeOption dateRange;
64	  final Set<EntrySource> entryTypes;
65	
66	  @override
67	  List<Object?> get props => [dateRange, entryTypes];
68	}
