import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/features/entries/domain/entities/entry.dart';
import 'package:cerne/features/records/domain/entities/date_range_filter.dart';
import 'package:flutter/material.dart';

/// Presentation-only — exists only inside this file (FR-004); no field of
/// this name exists anywhere in `RecordsEvent`/`RecordsState`/
/// `EntriesRepository`. Rendered for visual fidelity with the prototype but
/// never filters and never reaches the backend.
enum _CategoryChip { work, routine, rest, relationships }

const _categoryLabels = {
  _CategoryChip.work: 'trabalho',
  _CategoryChip.routine: 'rotina',
  _CategoryChip.rest: 'descanso',
  _CategoryChip.relationships: 'relações',
};

const _dateRangeLabels = {
  DateRangeOption.allTime: 'Todo o período',
  DateRangeOption.thisWeek: 'Esta semana',
  DateRangeOption.thisMonth: 'Este mês',
};

const _entryTypeLabels = {
  EntrySource.manual: 'manual',
  EntrySource.audio: 'áudio',
  EntrySource.photo: 'foto',
  EntrySource.chat: 'chat',
};

/// "Sheet de filtro" (prototype-extract.md §2.4). Seeded with the screen's
/// *current* applied criteria so re-opening reflects what's already applied,
/// not a reset form.
class FilterSheet extends StatefulWidget {
  const FilterSheet({
    super.key,
    required this.initialDateRange,
    required this.initialEntryTypes,
  });

  final DateRangeOption initialDateRange;
  final Set<EntrySource> initialEntryTypes;

  @override
  State<FilterSheet> createState() => _FilterSheetState();
}

class _FilterSheetState extends State<FilterSheet> {
  late DateRangeOption _dateRange = widget.initialDateRange;
  late Set<EntrySource> _entryTypes = {...widget.initialEntryTypes};

  // Local-only, never read outside this widget (FR-004).
  Set<_CategoryChip> _categoryChips = {};

  @override
  Widget build(BuildContext context) {
    return SafeArea(
      child: SingleChildScrollView(
        padding: const EdgeInsets.all(DesignTokens.spacingMd),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('INTERVALO DE DATA', style: _groupLabelStyle),
            const SizedBox(height: DesignTokens.spacingSm),
            Wrap(
              spacing: DesignTokens.spacingSm,
              children: [
                for (final option in DateRangeOption.values)
                  _FilterChip(
                    label: _dateRangeLabels[option]!,
                    selected: _dateRange == option,
                    onSelected: () => setState(() => _dateRange = option),
                  ),
              ],
            ),
            const SizedBox(height: DesignTokens.spacingMd),
            Text('CATEGORIA', style: _groupLabelStyle),
            const SizedBox(height: DesignTokens.spacingSm),
            Wrap(
              spacing: DesignTokens.spacingSm,
              children: [
                for (final chip in _CategoryChip.values)
                  _FilterChip(
                    label: _categoryLabels[chip]!,
                    selected: _categoryChips.contains(chip),
                    onSelected: () => setState(() {
                      _categoryChips = {..._categoryChips};
                      if (!_categoryChips.remove(chip)) _categoryChips.add(chip);
                    }),
                  ),
              ],
            ),
            const SizedBox(height: DesignTokens.spacingMd),
            Text('TIPO DE ENTRADA', style: _groupLabelStyle),
            const SizedBox(height: DesignTokens.spacingSm),
            Wrap(
              spacing: DesignTokens.spacingSm,
              children: [
                for (final source in EntrySource.values)
                  _FilterChip(
                    label: _entryTypeLabels[source]!,
                    selected: _entryTypes.contains(source),
                    onSelected: () => setState(() {
                      _entryTypes = {..._entryTypes};
                      if (!_entryTypes.remove(source)) _entryTypes.add(source);
                    }),
                  ),
              ],
            ),
            const SizedBox(height: DesignTokens.spacingLg),
            Row(
              children: [
                TextButton(
                  onPressed: () => setState(() {
                    _dateRange = DateRangeOption.allTime;
                    _entryTypes = {};
                    _categoryChips = {};
                  }),
                  child: const Text('Limpar'),
                ),
                const Spacer(),
                ElevatedButton(
                  onPressed: () => Navigator.pop(
                    context,
                    (dateRange: _dateRange, entryTypes: _entryTypes),
                  ),
                  child: const Text('Aplicar'),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  static final _groupLabelStyle = DesignTokens.textLabelMd.copyWith(
    color: DesignTokens.colorTextSecondary,
  );
}

class _FilterChip extends StatelessWidget {
  const _FilterChip({required this.label, required this.selected, required this.onSelected});

  final String label;
  final bool selected;
  final VoidCallback onSelected;

  @override
  Widget build(BuildContext context) {
    return ChoiceChip(
      label: Text(label),
      selected: selected,
      onSelected: (_) => onSelected(),
      selectedColor: DesignTokens.colorPrimary,
      backgroundColor: DesignTokens.colorSurfaceBg,
      side: const BorderSide(color: DesignTokens.colorBorder),
      labelStyle: TextStyle(
        color: selected ? DesignTokens.colorOnPrimary : DesignTokens.colorTextPrimary,
      ),
    );
  }
}

