1	import 'package:cerne/core/network/api_client.dart';
2	import 'package:cerne/core/network/failure.dart';
3	import 'package:cerne/features/entries/domain/entities/entries_page.dart';
4	import 'package:cerne/features/entries/domain/entities/entry.dart';
5	import 'package:fpdart/fpdart.dart';
6	
7	const _malformedEntriesFailure = ValidationFailure(
8	  message: 'Malformed entries response',
9	  requestId: '',
10	);
11	
12	/// The only class that calls `ApiClient.call('entries-create'/'entries-list'/
13	/// 'entries-get', ...)` and parses the [Entry]/[EntriesPage] response shapes
14	/// (data-model.md, contracts/entries-repository-extension.md). Never sends
15	/// `occurredAt`/`mediaDurationSeconds`/`chatMessageId` in a request body.
16	class EntriesRemoteDataSource {
17	  const EntriesRemoteDataSource(this._apiClient);
18	
19	  final ApiClient _apiClient;
20	
21	  Future<Either<Failure, Entry>> create({
22	    required String content,
23	    required EntrySource source,
24	  }) async {
25	    final result = await _apiClient.call(
26	      'entries-create',
27	      method: 'POST',
28	      body: {'content': content, 'source': source.name},
29	    );
30	
31	    return result.flatMap(_parseEntry);
32	  }
33	
34	  Future<Either<Failure, EntriesPage>> list({
35	    String? cursor,
36	    EntrySource? source,
37	    DateTime? dateFrom,
38	    DateTime? dateTo,
39	    int? limit,
40	  }) async {
41	    final queryParameters = <String, String>{
42	      'cursor': ?cursor,
43	      'source': ?source?.name,
44	      'dateFrom': ?dateFrom?.toUtc().toIso8601String(),
45	      'dateTo': ?dateTo?.toUtc().toIso8601String(),
46	      'limit': ?limit?.toString(),
47	    };
48	    final result = await _apiClient.call(
49	      'entries-list',
50	      method: 'GET',
51	      queryParameters: queryParameters.isEmpty ? null : queryParameters,
52	      unwrapData: false,
53	    );
54	
55	    return result.flatMap(_parseEntriesPage);
56	  }
57	
58	  Future<Either<Failure, Entry>> getById(String id) async {
59	    final result = await _apiClient.call(
60	      'entries-get',
61	      method: 'GET',
62	      pathSegments: [id],
63	    );
64	
65	    return result.flatMap(_parseEntry);
66	  }
67	
68	  Future<Either<Failure, List<Entry>>> search({
69	    String? q,
70	    EntrySource? source,
71	    DateTime? dateFrom,
72	    DateTime? dateTo,
73	    int limit = 50,
74	  }) async {
75	    final result = await _apiClient.call(
76	      'entries-search',
77	      method: 'GET',
78	      queryParameters: {
79	        if (q != null && q.isNotEmpty) 'q': q,
80	        if (source != null) 'source': source.name,
81	        if (dateFrom != null) 'dateFrom': dateFrom.toUtc().toIso8601String(),
82	        if (dateTo != null) 'dateTo': dateTo.toUtc().toIso8601String(),
83	        'limit': limit.toString(),
84	      },
85	      unwrapData: false,
86	    );
87	
88	    return result.flatMap(_parseSearchResults);
89	  }
90	
91	  Either<Failure, List<Entry>> _parseSearchResults(Map<String, dynamic> body) {
92	    try {
93	      final entries = (body['data'] as List<dynamic>)
94	          .map((e) => _parseEntryFields(e as Map<String, dynamic>))
95	          .toList();
96	      return Right(entries);
97	    } on TypeError {
98	      return const Left(_malformedEntriesFailure);
99	    } on FormatException {
100	      return const Left(_malformedEntriesFailure);
101	    }
102	  }
103	
104	  Either<Failure, Entry> _parseEntry(Map<String, dynamic> data) {
105	    try {
106	      return Right(_parseEntryFields(data));
107	    } on TypeError {
108	      return const Left(_malformedEntriesFailure);
109	    } on FormatException {
110	      return const Left(_malformedEntriesFailure);
111	    }
112	  }
113	
114	  // The full response body for `entries-list` is `{"data": [...], "meta":
115	  // {"nextCursor": ...}}` — `ApiClient.call(..., unwrapData: false)` returns
116	  // it verbatim since the inner "data" here is an array, not an object.
117	  Either<Failure, EntriesPage> _parseEntriesPage(Map<String, dynamic> body) {
118	    try {
119	      final entries = (body['data'] as List<dynamic>)
120	          .map((e) => _parseEntryFields(e as Map<String, dynamic>))
121	          .toList();
122	      final meta = body['meta'] as Map<String, dynamic>;
123	      return Right(
124	        EntriesPage(
125	          entries: entries,
126	          nextCursor: meta['nextCursor'] as String?,
127	        ),
128	      );
129	    } on TypeError {
130	      return const Left(_malformedEntriesFailure);
131	    } on FormatException {
132	      return const Left(_malformedEntriesFailure);
133	    }
